def f(expr):
    s = expr.replace(' ', '')
    precedence = {'+': 1, '-': 1, '*': 2}
    vals, ops = [], []

    def apply_op():
        op = ops.pop()
        b = vals.pop()
        a = vals.pop()
        if op == '+':
            vals.append(a + b)
        elif op == '-':
            vals.append(a - b)
        else:  # '*'
            vals.append(a * b)

    i = 0
    n = len(s)
    while i < n:
        ch = s[i]
        if ch.isdigit():
            num = 0
            while i < n and s[i].isdigit():
                num = num * 10 + int(s[i])
                i += 1
            vals.append(num)
            continue
        if ch == '(':
            ops.append(ch)
        elif ch == ')':
            while ops and ops[-1] != '(':
                apply_op()
            ops.pop()  # remove '('
        else:  # operator + - *
            while ops and ops[-1] != '(' and precedence[ops[-1]] >= precedence[ch]:
                apply_op()
            ops.append(ch)
        i += 1

    while ops:
        apply_op()
    return vals[-1] if vals else 0
```

